private static string StripComments(string source)
{
    source = source.Replace("\r\n", "\n");
    source = Regex.Replace(source, @"/\*.*?\*/", match => new string(' ', match.Length), RegexOptions.Singleline);
    source = Regex.Replace(source, @"//[^\n]*", match => new string(' ', match.Length));
    return source;
}
