    if (!_engine.TryGetService(CoreServiceKeys.NavQueryServices, out NavQueryServiceRegistry registry))
    {
        throw new InvalidOperationException(
            "NavMesh presentation is enabled but the NavQueryServices registry is not registered; " +
            "load a map with Feature.NavMesh:On before enabling the navmesh overlay.");
    }

    if (!_engine.TryGetService(CoreServiceKeys.NavMeshBakeConfig, out NavMeshBakeConfig bakeConfig))
    {
        throw new InvalidOperationException(
            "NavMesh presentation is enabled but NavMeshBakeConfig is not registered; " +
            "the navmesh bake configuration service is missing.");
    }

    if (!_engine.TryGetService(CoreServiceKeys.NavMeshProfiles, out NavMeshProfileRegistry profileRegistry))
    {
        throw new InvalidOperationException(
            "NavMesh presentation is enabled but NavMeshProfiles is not registered; " +
            "the agent profile registry is missing.");
    }

    NavMeshPresentationCapabilityValidator.Require(
        _engine.TryGetService(CoreServiceKeys.PresentationAdapterCapabilities, out PresentationAdapterCapabilities? capabilities)
            ? capabilities
            : null);

    if (!registry.TryGetStore(layer, profile, out NavTileStore store))
    {
        throw new InvalidOperationException(
            $"NavMesh presentation enabled with layer={layer}, profile={profile}, but no matching NavTileStore is registered.");
    }

    if (!store.TryRunStableRead(store.SnapshotLoadedTiles, out NavTile[]? loadedTiles) ||
        loadedTiles == null)
    {
        return;
    }

    int tileCount = Math.Min(loadedTiles.Length, _tileScratch.Length);
    _buffer.BeginFrame(
        layer,
        profile,
        profileRegistry.GetId(profile),
        bakeConfig.ParsedMode,
        bakeConfig.ParsedAlgorithm,
        store.Revision,
        _state.Revision,
        ResolveBuildConfig(bakeConfig),
        in style);
    for (int i = 0; i < tileCount; i++)
    {
        _buffer.AddTile(loadedTiles[i]);
    }
}

