                }

                for (int i = 0; i < chunkCount; i++)
                {
                    int cx = br.ReadInt32();
                    int cy = br.ReadInt32();
                    if ((uint)cx >= (uint)widthChunks || (uint)cy >= (uint)heightChunks)
                    {
                        throw new InvalidDataException($"Sparse React terrain '{inputName}' has chunk ({cx},{cy}) outside {widthChunks}x{heightChunks}.");
